// Monta o corpo do report (usado nos 2 ramos) + telefone do lead normalizado.
// Acesso SEGURO em tudo: num parcial as chaves de answers podem nem existir.
const CAMPOS = [["6aaaddcfa4bca4e9600e85d1", "Nome do lead"], ["6aaaddd56c2a75e13c08966b", "E-mail"], ["6aaadde91df41d26140f04ac", "Instagram"], ["6aaadddcbe3f86dae3002c09", "Whatsapp"], ["6aaaddf8be3f86dae3002c0d", "Faturamento"], ["6aaade2132f7eec6850bc625", "Momento no consórcio"], ["6aaade51bddcbf92400e11bb", "Volume de vendas mensal"], ["6aaade6f6adfe4385a080eb4", "Origem dos clientes"], ["6aaade921df41d26140f04b1", "Objetivo (próximos meses)"], ["6aaade991df41d26140f04b3", "Maior dificuldade hoje"], ["6aaadea3a4bca4e9600e85d4", "Por que resolver agora"], ["6aaadeaa1df41d26140f04b6", "Resultado que quer alcançar"], ["6aaadeb26adfe4385a080eb7", "Por que deveríamos selecionar você"], ["6aaadec11df41d26140f04b8", "Aberto a investir"], ["6aaaded71df41d26140f04ba", "Confirmou compromisso"]];
const resp = $('Trata Webhook').item.json.response || {};
const ans = resp.answers || {};
const val = (id) => {
  const c = ans[id]?.content;
  if (c === null || c === undefined) return '';
  if (c === true) return 'Sim';
  if (c === false) return 'Não';
  return Array.isArray(c) ? c.filter(Boolean).join(', ') : String(c);
};
// Campo vazio não vira linha: no parcial metade das perguntas não existe.
const linhas = CAMPOS.map(([id, rot]) => {
  const v = val(id);
  return v ? `*${rot}*: ${v}` : null;
}).filter(Boolean);
const t = resp.tracking || {};
const utm = ['utm_source', 'utm_campaign', 'utm_medium', 'utm_content', 'utm_term']
  .map((k) => `${k}: ${t[k] || ''}`).join('\n');
const report = linhas.join('\n\n')
  + '\n\n*Origens:*\nFormulário: Aplicação Pedros Ros (yay forms)\n\n' + utm;
// Z-API quer só dígitos com DDI; o Yay entrega '+5519971501794'.
let leadPhone = val('6aaadddcbe3f86dae3002c09').replace(/\D/g, '');
if (leadPhone && !leadPhone.startsWith('55')) leadPhone = '55' + leadPhone;
return [{ json: { ...$json, report, leadPhone } }];

// Link do Calendly do campo 6aaadf25bddcbf92400e11be. O Yay grava em 2 formatos:
//   https://calendly.com/scheduled_events/<uuid>/invitees/<uuid>
//   https://calendly.com/app/scheduled_events/user/me?period=all_time&uuid=<uuid>
// Os dois têm que casar — o detector dos funis do JP só pega o primeiro.
const F_CAL = '6aaadf25bddcbf92400e11be', F_FAT = '6aaaddf8be3f86dae3002c0d';
const DESQ = ["Ainda não faturo", "Até R$ 10 mil", "De R$ 10 mil a R$ 20 mil"];
const resp = $('Trata Webhook').item.json.response || {};
const ans = resp.answers || {};
const c = ans[F_CAL]?.content;
let eventUuid = null, link = null;
if (typeof c === 'string' && c.includes('calendly.com')) {
  const m = c.match(/scheduled_events\/([0-9a-fA-F-]{36})/) || c.match(/[?&]uuid=([0-9a-fA-F-]{36})/);
  if (m) { eventUuid = m[1]; link = c.trim(); }
}
// Rótulo do report do parcial. Só vale no ramo false (com link, vai pro ramo agendado).
const fat = ans[F_FAT]?.content?.[0] || '';
const completa = !!resp.submittedAt;
const situacao = !completa
  ? 'parcial — abandonou o formulário (não finalizou)'
  : (DESQ.includes(fat)
      ? 'desqualificado pelo faturamento (o form encerra antes do calendário)'
      : 'chegou no calendário e não agendou');
return [{ json: { ...$json, agendou: !!eventUuid, calendlyLink: link, eventUuid, completa, situacao } }];

// dia/hora BR do evento + os 2 guards do pré-call.
const ev = $('3 · Busca evento').item.json.resource;
const p = new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
}).formatToParts(new Date(ev.start_time));
const g = (t) => p.find((x) => x.type === t).value;
const dataHora = `${g('day')}/${g('month')} às ${g('hour')}:${g('minute')}`;       // msg ao lead
const dataHoraGrupo = `${g('day')}/${g('month')}/${g('year')} ${g('hour')}:${g('minute')}`;  // report
// Pré-call só em resposta COMPLETA (com parcial ligado o mesmo lead gera 2 webhooks)
// e só com evento ativo (agendou e cancelou antes do webhook -> não confirma nada).
const completa = $('1 · Detecta link Calendly').item.json.completa;
const ativo = ev.status === 'active';
const precallOk = completa && ativo;
// O grupo é avisado quando o report sai sem pré-call; string vazia no caso normal.
const alertaStatus = precallOk ? '' :
  `*⚠️ Sem pré-call automático* (${!ativo ? 'evento ' + ev.status : 'resposta parcial, aguardando o lead finalizar'})\n\n`;
return [{ json: { ...$json, dataHora, dataHoraGrupo, precallOk, alertaStatus,
  statusEvento: ev.status, joinUrl: ev.location?.join_url || '' } }];

